WITH with_prev AS (SELECT *, LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts ASC, id ASC) AS prev_reading_ts FROM device_readings), flagged AS (SELECT *, CASE WHEN prev_reading_ts IS NULL OR reading_ts > prev_reading_ts + INTERVAL 20 MINUTES THEN 1 ELSE 0 END AS is_new_session FROM with_prev), sessions_device_readings AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY device_code ORDER BY reading_ts ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM flagged) SELECT id, device_code, reading_ts, humidity, pressure, status_bits, prev_reading_ts, is_new_session, burst_id, CASE WHEN device_code RLIKE '^(DV-02|DV-01)$' THEN 'GROUP_B' ELSE 'CORE' END AS device_code_zone FROM sessions_device_readings ORDER BY prev_reading_ts ASC NULLS FIRST
